#![forbid(unsafe_code)]
use corsairs::{
    Cancel, Compute, CreatorValue, DType, Float8E4M3Fn, Float8E5M2, FunctionLoadRequest, Image, ImageMap, ModelLoadRequest,
    PixelFormat, Runtime, Tensor, TensorHandleMap, TensorMap,
};

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let assets = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("models");
    let runtime = Runtime::new()?;
    // v0.2/v0.3: concurrent loading and retained native chaining.
    let models = runtime
        .load_models(
            ["accumulator.aimodel", "feedforward.aimodel"]
                .map(|name| ModelLoadRequest {
                    path: assets.join(name),
                    options: Compute::CpuOnly.into(),
                })
                .into(),
        )
        .wait()?;
    let functions = runtime
        .load_functions(
            models
                .iter()
                .map(|model| FunctionLoadRequest {
                    model: model.clone(),
                    name: "main".into(),
                })
                .collect(),
        )
        .wait()?;
    let x = runtime
        .upload(Tensor::from_vec([2, 3], vec![1f32, -2., 3., 0., 5., -1.])?)
        .wait()?;
    let state = runtime.upload(Tensor::zeros(DType::Float32, [2, 3])?).wait()?;
    let first = functions[0]
        .run_native([("x", x)].into(), [("accumulator", state)].into())
        .wait()?;
    let carry = first.outputs.get("y").ok_or("missing carry")?.clone();
    drop(first);
    let result = functions[1].run_native([("x", carry)].into(), TensorHandleMap::new()).wait()?;
    let y = result.outputs.get("y").ok_or("missing y")?.download().wait()?;
    assert_eq!(y.to_vec::<f32>()?, [6., 5., 2., 0.]);
    println!("native chain: {:?}", y.to_vec::<f32>()?);

    // v0.4: Neural Engine preference on the same graph.
    let neural = runtime
        .load_model(assets.join("feedforward.aimodel"), Compute::NeuralEnginePreferred)
        .wait()?
        .load_function("main")
        .wait()?;
    let inputs = TensorMap::from([("x", Tensor::from_vec([2, 3], vec![1f32, -2., 3., 0., 5., -1.])?)]);
    let ane = neural.run(inputs, TensorMap::new()).wait()?;
    println!("neural-engine-preferred: {:?}", ane.outputs.get("y").ok_or("missing y")?.to_vec::<f32>()?);

    // v0.4: asset inspection without loading, and the device architecture.
    let info = runtime.inspect_asset(assets.join("feedforward.aimodel"), true).wait()?;
    let summary = info.summary.ok_or("missing summary")?;
    let operations: usize = summary.operations.iter().map(|o| o.count).sum();
    assert_eq!((summary.functions.len(), operations), (1, 21));
    println!("asset: {} function, {operations} operations; device {}", summary.functions.len(),
             runtime.device_architecture().wait()?);

    // v0.4: cancellation of a finished request reports TooLate.
    let done = runtime.flush();
    let handle = done.cancel_handle();
    done.wait()?;
    assert_eq!(handle.cancel(), Cancel::TooLate);
    let tensor = Tensor::from_vec([3], vec![0u8, 1, 255])?;
    assert_eq!(runtime.upload(tensor).wait()?.download().wait()?.to_vec::<u8>()?, [0, 1, 255]);
    println!("cancel: TooLate; u8 roundtrip: ok");

    // v0.4.1: float8 storage and conversion, DType::all(), and float8 inference.
    assert_eq!(DType::all().len(), 15);
    assert!(DType::all().contains(&DType::Float8E4M3Fn) && DType::all().contains(&DType::Float8E5M2));
    let values = [1.0f32, -2.0, 0.5, 448.0];
    let e4: Vec<_> = values.iter().map(|&v| Float8E4M3Fn::from_f32(v)).collect();
    let tensor = Tensor::from_vec([4], e4.clone())?;
    let back = runtime.upload(tensor).wait()?.download().wait()?.to_vec::<Float8E4M3Fn>()?;
    assert_eq!(back, e4);
    assert_eq!(back.iter().map(|v| v.to_f32()).collect::<Vec<_>>(), values);
    assert_eq!(Float8E5M2::from_f32(61440.0).to_f32(), f32::INFINITY);
    println!("float8: e4m3fn roundtrip and e5m2 overflow ok; dtypes {}", DType::all().len());

    // v0.5: packed image I/O on every compute preference.
    let pixels: Vec<u8> = (0..32).map(|i| (i * 7 + 3) as u8).collect();
    for compute in [Compute::CpuOnly, Compute::GpuPreferred, Compute::NeuralEnginePreferred] {
        let function = runtime
            .load_model(assets.join("bgra32_identity.aimodel"), compute)
            .wait()?
            .load_function("main")
            .wait()?;
        let descriptor = function.descriptor();
        assert_eq!(descriptor.image_inputs[0].format(), Some(PixelFormat::Bgra32));
        let images = ImageMap::from([("x", Image::new(PixelFormat::Bgra32, 4, 2, pixels.clone())?)]);
        let result = function.run_with_images(TensorMap::new(), images, TensorMap::new()).wait()?;
        assert_eq!(result.images.get("y").ok_or("missing image")?.as_bytes(), pixels);
    }
    println!("images: bgra32 identity exact on 3 backends");

    // v0.5: creator-defined asset metadata.
    let info = runtime.inspect_asset(assets.join("creator.aimodel"), false).wait()?;
    let creator = &info.metadata.creator_defined;
    assert_eq!(creator.get("string"), Some(&CreatorValue::String("plain".into())));
    assert_eq!(creator.get("integer_negative"), Some(&CreatorValue::Integer(-42)));
    assert_eq!(creator.get("number"), Some(&CreatorValue::Number(0.1)));
    assert_eq!(creator.get("bool_true"), Some(&CreatorValue::Bool(true)));
    println!("creator metadata: {} entries", creator.len());
    Ok(())
}
